// <auto-generated />
import { queryOptions, useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { UseQueryOptions, UseMutationOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import type { ApiService } from '../client/ApiService';
import { ApiError } from '../errors/ApiError';
import type { Resource, ResourceQuery } from '../models';

const resourcesKeys = {
  all: ['resources'] as const,
  list: () => [...resourcesKeys.all, 'list'] as const,
  query: (body: ResourceQuery) => [...resourcesKeys.all, 'query', body] as const,
};

export { resourcesKeys };

/**
 * The query options of each read: spread into useQuery or useSuspenseQuery, or pass to
 * queryClient.prefetchQuery / ensureQueryData (a route loader, server rendering). The query hands
 * React Query's signal to the client, so a cancelled or unused query stops its request.
 */
const resourcesQueries = {
  listResources: (api: ApiService) => queryOptions<Resource[], ApiError>({
    queryKey: resourcesKeys.list(),
    queryFn: async ({ signal }) => {
      const result = await api.resources.listResources(signal);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    retry: false,
  }),
  queryResources: (api: ApiService, body: ResourceQuery) => queryOptions<Resource[], ApiError>({
    queryKey: resourcesKeys.query(body),
    queryFn: async ({ signal }) => {
      const result = await api.resources.queryResources(body, signal);
      if (result.status === 'ok') {
        return result.data;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    retry: false,
  }),
};

export { resourcesQueries };

/** List resources */
export function useListResources(options?: Omit<UseQueryOptions<Resource[], ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    ...resourcesQueries.listResources(api),
    ...options,
  });
}

/** Query resources with a body */
export function useQueryResources(body: ResourceQuery, options?: Omit<UseQueryOptions<Resource[], ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    ...resourcesQueries.queryResources(api, body),
    enabled: !!body,
    ...options,
  });
}

/** Link a resource (custom verb) */
export function useLinkResource(options?: Omit<UseMutationOptions<void, ApiError, void>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async () => {
      const result = await api.resources.linkResource();
      if (result.status === 'noContent') {
        return;
      }
      if ('error' in result && result.error instanceof ApiError) {
        throw result.error;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: resourcesKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}